CREATE TABLE purchase_order_number_counters(tenant_id UUID NOT NULL REFERENCES organizations(id),order_year INTEGER NOT NULL,next_value BIGINT NOT NULL,PRIMARY KEY(tenant_id,order_year),CHECK(next_value>0));
CREATE TABLE purchase_orders(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,supplier_id UUID NOT NULL,warehouse_id UUID NOT NULL,purchase_order_number VARCHAR(32) NOT NULL,status VARCHAR(16) NOT NULL,supplier_number_snapshot VARCHAR(40) NOT NULL,supplier_name_snapshot VARCHAR(200) NOT NULL,supplier_legal_name_snapshot VARCHAR(200),warehouse_code_snapshot VARCHAR(40) NOT NULL,warehouse_name_snapshot VARCHAR(160) NOT NULL,currency CHAR(3) NOT NULL,payment_terms_days INTEGER,expected_delivery_date DATE,supplier_reference VARCHAR(120),internal_note VARCHAR(1000),supplier_note VARCHAR(1000),subtotal NUMERIC(19,6) NOT NULL DEFAULT 0,total NUMERIC(19,6) NOT NULL DEFAULT 0,order_date DATE,submitted_at TIMESTAMPTZ,approved_at TIMESTAMPTZ,approved_by UUID,sent_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,cancelled_by UUID,cancellation_reason VARCHAR(500),created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,purchase_order_number),UNIQUE(tenant_id,id,supplier_id),FOREIGN KEY(tenant_id,supplier_id) REFERENCES suppliers(tenant_id,id),FOREIGN KEY(tenant_id,warehouse_id) REFERENCES warehouses(tenant_id,id),CHECK(status IN('DRAFT','SUBMITTED','APPROVED','SENT','CANCELLED')),CHECK(currency~'^[A-Z]{3}$'),CHECK(payment_terms_days BETWEEN 0 AND 3650),CHECK(subtotal>=0 AND total=subtotal));
CREATE TABLE purchase_order_lines(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,purchase_order_id UUID NOT NULL,supplier_id UUID NOT NULL,supplier_product_id UUID NOT NULL,variant_id UUID NOT NULL,line_number INTEGER NOT NULL,supplier_sku_snapshot VARCHAR(128) NOT NULL,variant_sku_snapshot VARCHAR(128) NOT NULL,description_snapshot VARCHAR(300) NOT NULL,ordered_quantity NUMERIC(19,6) NOT NULL,purchase_unit_code VARCHAR(8) NOT NULL,base_units_per_purchase_unit NUMERIC(19,6) NOT NULL,base_quantity NUMERIC(19,6) NOT NULL,unit_cost NUMERIC(19,6) NOT NULL,currency CHAR(3) NOT NULL,line_subtotal NUMERIC(19,6) NOT NULL,expected_delivery_date DATE,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 0,UNIQUE(tenant_id,purchase_order_id,id),UNIQUE(tenant_id,purchase_order_id,line_number),UNIQUE(tenant_id,purchase_order_id,supplier_product_id),FOREIGN KEY(tenant_id,purchase_order_id,supplier_id) REFERENCES purchase_orders(tenant_id,id,supplier_id),FOREIGN KEY(tenant_id,supplier_product_id) REFERENCES supplier_products(tenant_id,id),FOREIGN KEY(tenant_id,variant_id) REFERENCES catalog_product_variants(tenant_id,id),CHECK(line_number>0),CHECK(ordered_quantity>0),CHECK(base_units_per_purchase_unit>0),CHECK(base_quantity=ordered_quantity*base_units_per_purchase_unit),CHECK(unit_cost>=0),CHECK(line_subtotal=ordered_quantity*unit_cost),CHECK(currency~'^[A-Z]{3}$'));
CREATE INDEX idx_po_status ON purchase_orders(tenant_id,status);CREATE INDEX idx_po_supplier_status ON purchase_orders(tenant_id,supplier_id,status);CREATE INDEX idx_po_warehouse_status ON purchase_orders(tenant_id,warehouse_id,status);CREATE INDEX idx_po_expected ON purchase_orders(tenant_id,expected_delivery_date);CREATE INDEX idx_po_created ON purchase_orders(tenant_id,created_at);CREATE INDEX idx_po_lines_variant ON purchase_order_lines(tenant_id,variant_id);CREATE INDEX idx_po_lines_supplier_product ON purchase_order_lines(tenant_id,supplier_product_id);
CREATE FUNCTION prevent_po_ownership_change() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.tenant_id<>OLD.tenant_id OR NEW.supplier_id<>OLD.supplier_id OR NEW.purchase_order_number<>OLD.purchase_order_number OR (OLD.status<>'DRAFT' AND NEW.warehouse_id<>OLD.warehouse_id) THEN RAISE EXCEPTION 'purchase order ownership is immutable' USING ERRCODE='55000';END IF;RETURN NEW;END$$;CREATE TRIGGER po_ownership_immutable BEFORE UPDATE ON purchase_orders FOR EACH ROW EXECUTE FUNCTION prevent_po_ownership_change();
CREATE FUNCTION validate_po_line_supplier() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NOT EXISTS(SELECT 1 FROM supplier_products p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.supplier_product_id AND p.supplier_id=NEW.supplier_id AND p.variant_id=NEW.variant_id) THEN RAISE EXCEPTION 'purchase order supplier product mismatch' USING ERRCODE='23514';END IF;RETURN NEW;END$$;CREATE TRIGGER po_line_supplier_guard BEFORE INSERT OR UPDATE ON purchase_order_lines FOR EACH ROW EXECUTE FUNCTION validate_po_line_supplier();
CREATE FUNCTION prevent_issued_po_line_change() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE s VARCHAR(16);t UUID;p UUID;BEGIN IF TG_OP='DELETE' THEN t=OLD.tenant_id;p=OLD.purchase_order_id;ELSE t=NEW.tenant_id;p=NEW.purchase_order_id;END IF;SELECT status INTO s FROM purchase_orders WHERE tenant_id=t AND id=p;IF s<>'DRAFT' THEN RAISE EXCEPTION 'issued purchase order lines are immutable' USING ERRCODE='55000';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END$$;CREATE TRIGGER po_line_issued_guard BEFORE INSERT OR UPDATE OR DELETE ON purchase_order_lines FOR EACH ROW EXECUTE FUNCTION prevent_issued_po_line_change();
INSERT INTO permissions(permission_key,description) VALUES('purchase-order:read','Read purchase orders'),('purchase-order:create','Create purchase orders'),('purchase-order:update','Update draft purchase orders'),('purchase-order:approve','Approve purchase orders'),('purchase-order:cancel','Cancel purchase orders') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(tenant_id,role_id,permission_key) SELECT r.tenant_id,r.id,p.permission_key FROM roles r CROSS JOIN permissions p WHERE r.system_role AND r.name='ORGANIZATION_ADMIN' AND p.permission_key LIKE 'purchase-order:%' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(tenant_id,role_id,permission_key) SELECT r.tenant_id,r.id,'purchase-order:read' FROM roles r WHERE r.system_role AND r.name IN('READ_ONLY','AUDITOR') ON CONFLICT DO NOTHING;
